import 'package:firebase_core/firebase_core.dart';
import 'package:flutter/material.dart';
import 'package:provider/provider.dart';

// Generated by `flutterfire configure` (see README.md).
import 'firebase_options.dart';
import 'screens/auth/login_screen.dart';
import 'screens/home_shell.dart';
import 'services/app_state.dart';
import 'services/notification_service.dart';
import 'theme.dart';

Future<void> main() async {
  WidgetsFlutterBinding.ensureInitialized();
  await Firebase.initializeApp(options: DefaultFirebaseOptions.currentPlatform);
  await NotificationService.init();
  runApp(
    ChangeNotifierProvider(
      create: (_) => AppState(),
      child: const PetCareHubApp(),
    ),
  );
}

class PetCareHubApp extends StatelessWidget {
  const PetCareHubApp({super.key});

  @override
  Widget build(BuildContext context) {
    return MaterialApp(
      title: 'PetCareHub',
      debugShowCheckedModeBanner: false,
      theme: buildTheme(),
      home: const AuthGate(),
    );
  }
}

/// Shows the login screen or the main app depending on auth state.
class AuthGate extends StatelessWidget {
  const AuthGate({super.key});

  @override
  Widget build(BuildContext context) {
    final state = context.watch<AppState>();
    if (!state.authResolved) {
      return const Scaffold(
        body: Center(child: CircularProgressIndicator()),
      );
    }
    return state.user == null ? const LoginScreen() : const HomeShell();
  }
}
